#!/usr/bin/env python3
"""Build a report from the user-selected HWPX style assets (Python 3 + lxml)."""
from pathlib import Path
from copy import deepcopy
from lxml import etree as E
import argparse, json, zipfile, math, unicodedata

ROOT = Path(__file__).resolve().parents[1]
NS = {'hp':'http://www.hancom.co.kr/hwpml/2011/paragraph',
      'hh':'http://www.hancom.co.kr/hwpml/2011/head',
      'hc':'http://www.hancom.co.kr/hwpml/2011/core'}
W = 48190

def tag(name): return '{'+NS['hp']+'}'+name

def text_run(cp, text):
    r = E.Element(tag('run'), charPrIDRef=str(cp))
    E.SubElement(r, tag('t')).text = str(text)
    return r

class Report:
    def __init__(self):
        self.assets = ROOT/'assets'
        self.section = E.parse(str(self.assets/'section.xml')).getroot()
        self.header = E.parse(str(self.assets/'header.xml')).getroot()
        self.section_control = self.section[0]
        self.section.remove(self.section_control)
        self.serial = 2000000000
        self.zserial = 0
        self.texts = []
        self.single_borders = {}
        fills = self.header.find('.//hh:borderFills',NS)
        next_id = max(int(x.get('id')) for x in fills)+1
        for kind,source_id in [('header',13),('body',11),('subtotal',21),('total',24)]:
            border = deepcopy(fills.find('hh:borderFill[@id="'+str(source_id)+'"]',NS))
            border.set('id',str(next_id))
            for side in ['leftBorder','rightBorder']:border.find('hh:'+side,NS).set('type','NONE')
            fills.append(border);self.single_borders[kind]=next_id;next_id+=1
        fills.set('itemCnt',str(len(fills)))

    def fresh(self, element):
        for node in element.iter():
            for key in ['id', 'instid', 'instId', 'zOrder']:
                if key in node.attrib and node.get(key):
                    if key == 'zOrder':
                        self.zserial += 1
                        node.set(key,str(self.zserial))
                    else:
                        self.serial += 1
                        node.set(key, str(self.serial))
        return element

    def clone(self, name):
        return self.fresh(E.parse(str(self.assets/(name+'.xml'))).getroot())

    def p(self, pp, runs, page_break=False):
        p = E.Element(tag('p'), id='0', paraPrIDRef=str(pp), styleIDRef='0',
                      pageBreak='1' if page_break else '0', columnBreak='0', merged='0')
        for cp, text in runs: p.append(text_run(cp, text))
        self.section.append(self.fresh(p))
        self.texts.append(''.join(str(t) for _,t in runs))
        return p

    def blank(self, size=4):
        self.p(0, [(24 if size==4 else 17, '')])

    def title(self, line1, line2):
        p = self.clone('title')
        first_run=p.find('hp:run',NS)
        for run in self.section_control:
            for node in run:
                if E.QName(node).localname in ('secPr','ctrl'):
                    first_run.insert(0,deepcopy(node))
        paragraphs=p.findall('.//hp:tbl/hp:tr/hp:tc/hp:subList/hp:p',NS)
        paragraphs[1].append(text_run(11,line1))
        paragraphs[2].append(text_run(12,line2))
        self.section.append(p); self.texts += [line1,line2]
        self.blank()

    def block(self, b):
        kind=b['type']; text=str(b.get('text','')); label=str(b.get('label',''))
        if kind=='heading':
            p=self.clone('heading');p.find('hp:run/hp:t',NS).text=' '+text
            self.section.append(p);self.texts.append(text);self.blank(size=6)
        elif kind in ('bullet','dash','note','warning'):
            pp,cp,prefix={'bullet':(45,18,' ㅇ '),'dash':(46,18,'   - '),
                          'note':(48,32,'    * '),'warning':(50,34,'    ※ ')}[kind]
            runs=[(cp,prefix)]
            if label:runs.append((22 if kind in ('bullet','dash') else cp,'('+label+') '))
            runs.append((cp,text));self.p(pp,runs)
            self.blank()
        elif kind=='attachment':
            p=self.clone('attachment');p.set('pageBreak','1')
            cells=p.findall('.//hp:tc',NS)
            cells[0].find('.//hp:t',NS).text='붙 임'
            cells[2].find('.//hp:t',NS).text=' '+text
            self.section.append(p);self.texts.append('붙임 '+text);self.blank()
        elif kind=='table':self.table(b)
        elif kind=='blank':self.blank()
        elif kind=='page_break':self.p(0,[(24,'')],True)
        else:raise ValueError('Unsupported block: '+kind)

    def table(self, b):
        headers=b['headers']; rows=b['rows']; n=len(headers)
        if n<1:raise ValueError('Table needs headers')
        widths=b.get('widths') or [W//n]*n
        if not b.get('widths'):widths[-1]+=W-sum(widths)
        if len(widths)!=n or any(w<=0 for w in widths) or sum(widths)!=W:
            raise ValueError('Column widths must be positive and sum to '+str(W))
        numeric=set(b.get('numeric_columns',[]))
        if any(i<0 or i>=n for i in numeric):raise ValueError('Invalid numeric column')
        def row_height(values):
            counts=[]
            for ci,(width,value) in enumerate(zip(widths,values)):
                # Conservative CJK width at 10pt (11pt in numeric columns), with 15% slack.
                em=1100 if ci in numeric else 1000
                capacity=max(1,width-1020)
                lines=0
                for part in str(value).split('\n'):
                    used=0;count=1
                    for ch in part:
                        if unicodedata.combining(ch):continue
                        factor=1 if unicodedata.east_asian_width(ch) in ('W','F') else .65
                        advance=em*factor*1.15
                        if used and used+advance>capacity:count+=1;used=0
                        used+=advance
                    lines+=count
                counts.append(max(1,lines))
            return max(1530,max(counts)*1650+282)
        if not b.get('_chunked'):
            # Hancom can clip oversized treatAsChar tables. Split physically and repeat headers.
            chunks=[];chunk=[];height=row_height(headers)
            for row in rows:
                values=row['cells'] if isinstance(row,dict) else row
                if len(values)!=n:raise ValueError('Row width mismatch')
                rh=row_height(values)
                if rh+row_height(headers)>58000:raise ValueError('A table row is too tall; shorten, widen or divide the row')
                if chunk and height+rh>58000:
                    chunks.append(chunk);chunk=[];height=row_height(headers)
                chunk.append(row);height+=rh
            if chunk:chunks.append(chunk)
            if len(chunks)>1:
                for i,chunk in enumerate(chunks):self.table({**b,'rows':chunk,'_chunked':True,'_page_break':i>0})
                return
        t=self.clone('table');total=0
        for zone in t.findall('hp:cellzoneList',NS):t.remove(zone)
        t.set('colCnt',str(n));t.set('rowCnt',str(len(rows)+1));t.set('repeatHeader','1')
        for ri, row in enumerate([{'cells':headers,'kind':'header'}]+rows):
            row=row if isinstance(row,dict) else {'cells':row}
            cells=row['cells'];kind=row.get('kind','body')
            if len(cells)!=n:raise ValueError('Row width mismatch')
            if kind not in ('header','body','subtotal','total'):raise ValueError('Invalid row kind')
            tr=E.SubElement(t,tag('tr'))
            # Deliberately allocate enough height for multiline text; never squeeze font to fit.
            rh=row_height(cells);total+=rh
            for ci,(value,width) in enumerate(zip(cells,widths)):
                c=self.clone('cell');tr.append(c)
                bf={'header':13,'body':11,'subtotal':21,'total':24}[kind]
                # Preserve sample's open outer sides with matching fill variants.
                if ci==0:bf={'header':12,'body':15,'subtotal':20,'total':23}[kind]
                if ci==n-1:bf={'header':14,'body':16,'subtotal':22,'total':25}[kind]
                if n==1:bf=self.single_borders[kind]
                c.set('borderFillIDRef',str(bf));c.set('header','1' if ri==0 else '0')
                c.find('hp:cellAddr',NS).set('colAddr',str(ci));c.find('hp:cellAddr',NS).set('rowAddr',str(ri))
                span=c.find('hp:cellSpan',NS);span.set('colSpan','1');span.set('rowSpan','1')
                sz=c.find('hp:cellSz',NS);sz.set('width',str(width));sz.set('height',str(rh))
                margin=c.find('hp:cellMargin',NS);margin.set('left','510');margin.set('right','510')
                sub=c.find('hp:subList',NS)
                for p in list(sub):sub.remove(p)
                cp=7 if kind=='header' else (35 if ci in numeric else 7) if kind in ('subtotal','total') else 37 if ci in numeric else 47
                pp=22 if kind=='header' or ci not in numeric else 35
                for line in str(value).split('\n'):
                    p=E.SubElement(sub,tag('p'),id='0',paraPrIDRef=str(pp),styleIDRef='0',pageBreak='0',columnBreak='0',merged='0')
                    p.append(text_run(cp,line))
                self.fresh(c)
            self.texts.append(' | '.join(map(str,cells)))
        t.find('hp:sz',NS).set('width',str(W));t.find('hp:sz',NS).set('height',str(total))
        p=self.p(0,[(28,'')],page_break=b.get('_page_break',False));p[0].insert(0,t)
        self.blank()

    def save(self, path, title):
        path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
        scaffold=self.assets/'package'
        metadata=E.parse(str(scaffold/'Contents/content.hpf')).getroot()
        for node in metadata.xpath('//*[local-name()="title"]'):node.text=title
        # Original business preview is never copied. Generated text describes this output only.
        with zipfile.ZipFile(path,'w') as z:
            z.write(scaffold/'mimetype','mimetype',compress_type=zipfile.ZIP_STORED)
            for file in sorted(scaffold.rglob('*')):
                if file.is_file() and file.name!='mimetype' and file.name!='content.hpf':
                    z.write(file,str(file.relative_to(scaffold)),compress_type=zipfile.ZIP_DEFLATED)
            for name,root in [('Contents/header.xml',self.header),('Contents/section0.xml',self.section),('Contents/content.hpf',metadata)]:
                z.writestr(name,E.tostring(root,encoding='UTF-8',xml_declaration=True),compress_type=zipfile.ZIP_DEFLATED)
            z.writestr('Preview/PrvText.txt','\n'.join(self.texts),compress_type=zipfile.ZIP_DEFLATED)
        validate(path)
        return path

def validate(path):
    with zipfile.ZipFile(path) as z:
        assert z.namelist()[0]=='mimetype' and z.getinfo('mimetype').compress_type==0
        assert z.read('mimetype')==b'application/hwp+zip'
        for name in z.namelist():
            if name.endswith(('.xml','.hpf','.rdf')):E.fromstring(z.read(name))
        section=E.fromstring(z.read('Contents/section0.xml'))
        assert not section.findall('.//hp:linesegarray',NS), 'Stale layout cache'
        for attr in ('id','instid'):
            ids=[x.get(attr) for x in section.iter() if x.get(attr) not in (None,'','0')]
            assert len(ids)==len(set(ids)), 'Duplicate '+attr
    return True

def build(data,path):
    r=Report();title=data['title']
    if len(title)!=2:raise ValueError('title needs exactly two lines')
    r.title(*title)
    for b in data['blocks']:r.block(b)
    return r.save(path,' '.join(title))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('input',type=Path);p.add_argument('-o','--output',required=True,type=Path)
    args=p.parse_args();print(build(json.loads(args.input.read_text(encoding='utf-8')),args.output))

