'use strict';
let DATA, entries=[];
const $=s=>document.querySelector('.skill-catalog '+s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats=['전체','기록·문서','설계·시각화','영상·미디어','기획·리서치','개발·검증','운영·연결'],symbols=['Aa / NOTE','◇ → □','▶ / FRAME','? → IDEA','{ CODE }','↗ / LINK'];
const safeUrl=u=>/^https?:\/\//i.test(String(u))?String(u):'#';
const sourceLink=(p,n)=>p?.manifest?.files?.find(f=>f.path===n)?.url||p?.manifest?.source?.skill_md_url||'';
const tabs=['사용 목적','SKILL.md','패키지 파일','설치·업데이트','삭제 영향','AI 명세'];
let category='전체',page=1,selected=null,activeTab=0,selectedFile='SKILL.md',copyText='',toastTimer;
function art(x){
 const i=Math.max(0,cats.indexOf(x.category)-1),title=esc(x.title),slug=esc(x.name);
 if(x.name==='diagram-design')return `<div class="art cover-architecture"><span class="cover-label">DIAGRAM DESIGN / EXAMPLE</span><div class="diagram-board"><img src="data:image/svg+xml;base64," alt="Diagram Design에 동봉된 Content site 아키텍처 도식 예시"></div><span class="cover-kind">동봉 예시 · Content site</span></div>`;
 if(x.category==='영상·미디어')return `<div class="art cover-motion"><span class="cover-label">MOTION / WORKFLOW</span><span class="film-count">01 — 03</span><h4 class="film-title">${title}</h4><span class="film-sub">${slug}</span><div class="film-track"><span></span><span></span><span></span></div><span class="cover-kind">용도 표지 · 영상 결과물 아님</span></div>`;
 if(x.category==='개발·검증'||x.name==='handoff'){
 const text=x.package?.texts['SKILL.md']||('name: '+x.name+'\ndescription: '+x.original);
 return `<div class="art cover-raw"><span class="cover-label">SOURCE / SKILL NOTES</span><div class="editor"><div class="editor-bar">● ● ●　　${slug} / SKILL.md</div><code>${esc(text.slice(0,580))}</code></div><span class="cover-kind">${x.package?'설치본 지침 발췌':'설명 메타데이터 발췌'}</span></div>`;
 }
 return `<div class="art cover-tone-${i}"><span class="cover-label">${esc(x.category)} / FIELD LIBRARY</span><div class="cover-sheet"><div class="document-name">${slug}</div><h4>${title}</h4><div class="source-lines">${esc(x.original.slice(0,270))}</div></div><span class="cover-kind">설명 메타데이터 기반 표지</span></div>`;
}

function filtered(){const q=$('#search').value.trim().toLowerCase(),scope=$('#scope').value,platform=$('#platform').value;const rows=entries.filter(x=>(category==='전체'||x.category===category)&&(scope==='all'||(scope==='examples'?!!x.package:x.scope==='direct'))&&(platform==='all'||x.platforms.includes(platform))&&(!q||[x.title,x.name,x.summary,x.origin].join(' ').toLowerCase().includes(q)));const sort=$('#sort').value;return rows.sort((a,b)=>sort==='rank'?a.rank-b.rank:sort==='saved'?((Date.parse(b.saved_at||b.installed_at||b.modified)||0)-(Date.parse(a.saved_at||a.installed_at||a.modified)||0)||a.name.localeCompare(b.name,'ko')):sort==='recent'?(String(b.created||b.modified).localeCompare(String(a.created||a.modified))||a.name.localeCompare(b.name,'ko')):sort==='modified'?b.modified.localeCompare(a.modified):String(a[sort==='source'?'origin':sort]).localeCompare(String(b[sort==='source'?'origin':sort]),'ko'))}
function fitNames(){document.querySelectorAll('.name-text').forEach(t=>{t.style.fontSize='';const box=t.parentElement;let size=parseFloat(getComputedStyle(box).fontSize);while((t.getBoundingClientRect().height>box.clientHeight+1||t.scrollWidth>box.clientWidth+1)&&size>12){size-=.5;t.style.fontSize=size+'px'}})}
window.addEventListener('resize',fitNames);
function render(){const rows=filtered(),total=Math.max(1,Math.ceil(rows.length/16));page=Math.min(page,total);$('#filters').innerHTML=cats.map(c=>`<button class="${c===category?'active':''}" data-cat="${esc(c)}" aria-pressed="${c===category}">${c}</button>`).join('');$('#count').textContent=`${rows.length}개 스킬 · ${page} / ${total} 페이지`;$('#grid').innerHTML=rows.slice((page-1)*16,page*16).map(x=>`<button class="card" data-open="${esc(x.id)}"><div class="name-cover tone-${Math.max(0,cats.indexOf(x.category)-1)}"><span class="cover-category">${esc(x.category)} / SKILL</span><h2 class="skill-name" title="${esc(x.name)}"><span class="name-text">${esc(x.name)}</span></h2></div><div class="card-body"><span class="cat">${esc(x.category)}</span><p class="skill-purpose">${esc(x.title)}</p><p class="summary">${esc(x.summary)}</p></div><div class="card-foot"><span>${esc(x.platforms.join(' · '))}</span><span class="${x.package?'ready':''}">${x.package?'원문·파일 상세 ↗':'사용 목적 ↗'}</span></div></button>`).join('')||'<p class="empty">조건에 맞는 스킬이 없습니다.</p>';requestAnimationFrame(fitNames);$('#pages').innerHTML=total<=1?'':Array.from({length:total},(_,i)=>`<button class="${page===i+1?'active':''}" ${page===i+1?'aria-current="page"':''} data-page="${i+1}">${i+1}</button>`).join('')}
function showDetail(id){selected=entries.find(x=>x.id===id);if(!selected)return;activeTab=0;selectedFile='SKILL.md';$('#title').textContent=selected.name;$('#detail-category').textContent=selected.category;$('#detail-slug').textContent=selected.title+' · '+selected.origin;renderDetail();$('#detail').showModal()}
function codeView(text,name){copyText=text;return `<div class="codehead"><span>${esc(name)}</span><button class="action" data-copy="text">표시 내용 복사</button></div><pre id="source-text">${esc(text)}</pre>`}
function renderDetail(){const x=selected,p=x.package,m=p?.manifest;$('#tabs').innerHTML=tabs.map((t,i)=>`<button data-tab="${i}" class="${activeTab===i?'active':''}" aria-current="${activeTab===i?'page':'false'}">${t}</button>`).join('');let html='';
